body:
This will keep scroll bar at the same position, but will result in the extremely jumpy behavior as line breaking changes.

It probably would make more sense to store first visible (on screen) character index instead, something like (this does not account for tables, which will require nested check for each cell lines):

```diff
diff --git a/scene/gui/rich_text_label.cpp b/scene/gui/rich_text_label.cpp
index 3ef71c3979..082a192308 100644
--- a/scene/gui/rich_text_label.cpp
+++ b/scene/gui/rich_text_label.cpp
@@ -4113,7 +4113,27 @@ bool RichTextLabel::_validate_line_caches() {

                // Update fonts.
                float old_scroll = vscroll->get_value();
-               float old_max = vscroll->get_max();
+               int old_first_char = 0;
+               {
+                       int to_line = main->first_invalid_line.load();
+                       for (int i = 0; i < to_line; i++) {
+                               MutexLock lock(main->lines[i].text_buf->get_mutex());
+                               int lc = main->lines[i].text_buf->get_line_count();
+                               float line_offset = 0.f;
+                               for (int j = 0; j < lc; j++) {
+                                       line_offset += main->lines[i].text_buf->get_line_ascent(j) + main->lines[i].text_buf->get_line_descent(j) + theme_cache.line_separation;
+                                       if (main->lines[i].offset.y + line_offset + line_offset > old_scroll) {
+                                               old_first_char = main->lines[i].char_offset + main->lines[i].text_buf->get_line_range(j).x;
+                                               break;
+                                       }
+                               }
+                               if (main->lines[i].offset.y + line_offset + line_offset > old_scroll) {
+                                       break;
+                               }
+                       }
+               }
+
+               //float old_max = vscroll->get_max();
                if (main->first_invalid_font_line.load() != (int)main->lines.size()) {
                        for (int i = main->first_invalid_font_line.load(); i < (int)main->lines.size(); i++) {
                                _update_line_font(main, i, theme_cache.normal_font, theme_cache.normal_font_size);
@@ -4142,11 +4162,25 @@ bool RichTextLabel::_validate_line_caches() {
                        main->first_resized_line.store(i);
                }
                if (!(scroll_follow && scroll_following)) {
-                       float scaled_old_scroll = old_scroll;
-                       if (old_max > 0.0f) {
-                               scaled_old_scroll = total_height * old_scroll / old_max;
+                       int to_line = main->first_invalid_line.load();
+                       for (int i = 0; i < to_line; i++) {
+                               MutexLock lock(main->lines[i].text_buf->get_mutex());
+                               int char_offset = main->lines[i].char_offset;
+                               int char_count = main->lines[i].char_count;
+                               if (char_offset <= old_first_char && old_first_char < char_offset + char_count) {
+                                       int lc = main->lines[i].text_buf->get_line_count();
+                                       float line_offset = 0.f;
+                                       for (int j = 0; j < lc; j++) {
+                                               line_offset += main->lines[i].text_buf->get_line_ascent(j) + main->lines[i].text_buf->get_line_descent(j) + theme_cache.line_separation;
+                                               Vector2i range = main->lines[i].text_buf->get_line_range(j);
+                                               if (char_offset + range.x <= old_first_char && old_first_char < char_offset + range.y) {
+                                                       vscroll->set_value(main->lines[i].offset.y + line_offset);
+                                                       break;
+                                               }
+                                       }
+                                       break;
+                               }
                        }
-                       vscroll->set_value(scaled_old_scroll);
                }
                main->first_resized_line.store(main->lines.size());
```
